mapper.select:
SELECT q.*,
       (e.first_name || ' ' || e.last_name) AS employee_name,
       e.employee_code,
       u.display_name AS assigned_hr_name,
       u.email AS assigned_hr_email
FROM hr_queries q
INNER JOIN employees e ON e.id = q.employee_id
LEFT JOIN users u ON u.id = q.assigned_hr_id
WHERE q.company_id = #{companyId}

    AND q.employee_id = #{employeeId}


    AND q.assigned_hr_id = #{assignedHrId}


    AND q.status = #{status}

ORDER BY q.id DESC
